function codexAccountMarkup(items:CodexAccount[]){return items.length?`<div class="account-grid">${items.map(a=>`<div class="account codex-account"><div><strong>${h(a.email||a.label)}</strong><span>${h(a.account_id||'계정 ID 없음')}</span></div><span class="account-status ${a.active?'active':''}">${a.active?'사용 중':'대기'}</span><button data-codex-select="${h(a.id)}" class="ghost" ${a.active?'disabled':''}>선택</button><button data-codex-remove="${h(a.id)}" class="danger">로그아웃</button></div>`).join('')}</div>`:'<div class="empty compact">Codex에 로그인된 계정이 없습니다.</div>'}
function bindCodexAccountButtons(){document.querySelectorAll<HTMLButtonElement>("[data-codex-select]").forEach(b=>b.onclick=async()=>{await api(`/auth/codex/accounts/${b.dataset.codexSelect}/select`,{method:"PUT"});toast("사용할 Codex 계정을 바꿨습니다.");collection('model')});document.querySelectorAll<HTMLButtonElement>("[data-codex-remove]").forEach(b=>b.onclick=async()=>{if(!confirm("이 장치의 KNU Server에서 Codex 계정을 로그아웃할까요?\nCodmes나 ChatGPT 계정은 영향받지 않습니다."))return;await api(`/auth/codex/accounts/${b.dataset.codexRemove}`,{method:"DELETE"});toast("계정을 로그아웃했습니다.");collection('model')});}
