function crawlSourceSummary(source:any){const total=Number(source.discovered||0),processed=Number(source.processed||0),saved=Number(source.saved||0),failed=Number(source.failed||0),percent=total?Math.round(processed/total*100):0;return `<button class="crawl-source-card ${activeNoticeSource===source.code?'selected':''}" data-crawl-source="${h(source.code)}"><span>${h(source.name||source.code)}</span><strong>${h(processed)} / ${h(total)}</strong><small>원문 확보 ${h(saved)} · 실패 ${h(failed)}</small><i><b style="width:${percent}%"></b></i></button>`;}
function crawlNoticeDetail(notice:any){const attachments=Object.values(notice.attachments||{}) as any[];return `<div class="notice-progress-detail"><div class="notice-stage"><span class="status-dot ${h(notice.status)}"></span><div><strong>${h(notice.stage||crawlStatusLabel(notice.status))}</strong>${notice.error?`<small>${h(notice.error)}</small>`:''}</div></div>${attachments.length?`<div class="attachment-progress"><h5>첨부파일 ${attachments.length}개</h5>${attachments.map(att=>`<div><span class="status-dot ${h(att.status)}"></span><strong>${h(att.name)}</strong><small>${h(att.stage||crawlStatusLabel(att.status))}${att.size?` · ${formatBytes(att.size)}`:''}${att.error?` · ${h(att.error)}`:''}</small></div>`).join('')}</div>`:'<p class="muted">첨부파일 없음</p>'}</div>`;}
function crawlSourceProgress(source:any,showSource:boolean){const pages=Object.values(source.pages||{}).sort((a:any,b:any)=>Number(a.page)-Number(b.page)) as any[];return `<div class="crawl-source-progress">${showSource?`<h4>${h(source.name||source.code)}</h4>`:''}<div class="crawl-page-list">${pages.map(page=>{const notices=Object.values(page.notices||{}) as any[];const done=notices.filter(n=>['complete','failed','skipped','excluded'].includes(n.status)).length;const pageKey=`${source.code}:${page.page}`;return `<details data-progress-page="${h(pageKey)}" ${page.status==='processing'||expandedProgressPages.has(pageKey)?'open':''}><summary><div><strong>${h(page.page)}페이지</strong><span>${notices.length}건 · ${done}/${notices.length} 처리 · 실패 ${h(page.failed||0)}</span></div><em>${h(crawlStatusLabel(page.status))}</em></summary><div class="crawl-notices">${notices.map(notice=>`<article class="crawl-notice ${h(notice.status)}"><span class="status-dot ${h(notice.status)}"></span><div><strong>${h(notice.title||'제목 확인 중')}</strong><small>${h(notice.stage||crawlStatusLabel(notice.status))}</small></div><div class="crawl-notice-actions">${notice.document_id?`<button class="text-link" data-notice="${h(notice.document_id)}">저장 데이터</button>`:''}<button class="text-link" data-progress-notice="${h(notice.url)}">${expandedProgressNotice===notice.url?'접기':'자세히 보기'}</button></div>${expandedProgressNotice===notice.url?crawlNoticeDetail(notice):''}</article>`).join('')}</div></details>`}).join('')}</div></div>`;}
function crawlProgressMarkup(run:any){const sources=Object.values(run?.sources||{}) as any[];if(!sources.length)return '';const selected=sources.find(source=>source.code===activeNoticeSource);const visibleSources=activeNoticeSource?(selected?[selected]:[]):sources;const badge=crawlStatusLabel(run.status==='running'?'processing':run.status);return `<section class="crawl-live panel"><div class="list-head"><div><h3>수집 현황</h3><p class="muted">비정상 종료 후에도 공지·첨부별 진행 목록을 유지합니다.</p></div><span class="live-badge ${h(run.status)}">${h(badge)}</span></div><div class="crawl-source-cards">${sources.map(crawlSourceSummary).join('')}</div>${visibleSources.length?visibleSources.map(source=>crawlSourceProgress(source,!activeNoticeSource)).join(''):'<div class="crawl-source-hint">수집 진행 정보가 아직 없습니다.</div>'}</section>`;}
