const documentInternalKinds=new Set(["attachment_hwp_structure","attachment_hwp_markdown","attachment_hwp_validation","attachment_hwp_image","attachment_hwp_binary","attachment_document_image","inline_image"]);
function attachmentMarkup(asset:Asset){return `<details><summary>${h(asset.filename||asset.kind)}</summary><pre>${h(asset.extracted_text||'추출 텍스트 없음')}</pre>${asset.source_url?`<button class="text-link" data-external-url="${h(asset.source_url)}">첨부 원본 열기</button>`:''}</details>`;}
function qualityMarkup(asset:Asset|undefined){if(!asset)return '<p class="muted">구조·품질 정보 없음</p>';try{const value=JSON.parse(asset.extracted_text||'{}');return `<dl class="quality-grid"><dt>판정</dt><dd>${h(value.status||'없음')}</dd><dt>품질 점수</dt><dd>${value.score==null?'없음':h(Math.round(Number(value.score)*1000)/10+'%')}</dd><dt>본문 일치도</dt><dd>${value.textTokenF1==null?'없음':h(Math.round(Number(value.textTokenF1)*1000)/10+'%')}</dd><dt>표</dt><dd>${h(value.tableCount??0)}개 · 셀 ${h(value.tableCellCount??0)}개</dd></dl>`;}catch{return `<pre>${h(asset.extracted_text||'품질 정보 없음')}</pre>`;}}
function documentAnalysisMarkup(assets:Asset[]){if(!assets.length)return '';const structure=assets.find(a=>a.kind==="attachment_hwp_structure");const markdown=assets.some(a=>a.kind==="attachment_hwp_markdown");const validation=assets.some(a=>a.kind==="attachment_hwp_validation");const images=assets.filter(a=>a.kind==="attachment_hwp_image"||a.kind==="attachment_document_image"||a.kind==="inline_image").sort((a,b)=>Number(a.extra?.figure?.number??999)-Number(b.extra?.figure?.number??999));const binaries=assets.filter(a=>a.kind==="attachment_hwp_binary");return `<details class="processing-results"><summary>본문·문서 그림 처리 상세 · 내부 파일 ${assets.length}개</summary><p class="muted">공지 본문과 HWP·HWPX·PDF·Word·Excel·PowerPoint의 검증된 그림 설명만 번호와 문맥을 포함해 검색에 사용합니다.</p>${structure?qualityMarkup(structure):''}${structure?`<div class="process-flags"><span>${markdown?'✓':'—'} 검색용 Markdown</span><span>${validation?'✓':'—'} HWPX 교차 검증</span></div>`:''}${images.length?`<h4>본문·문서 그림 ${images.length}개</h4><div class="asset-images">${images.map(a=>{const figure=a.extra?.figure;const analysis=a.extra?.analysis;const label=figure?.label||a.filename||'문서 내부 이미지';return `<figure><div class="asset-preview"><span>미리보기 불러오는 중…</span><img data-asset-preview="${a.id}" alt="${h(label)}"/></div><figcaption><strong>${h(label)} · ${h(a.filename)}</strong><span>${h(analysis?.description||'이미지 설명은 아직 생성되지 않았습니다.')}</span>${figure?.context?`<details class="image-context"><summary>문서 내 위치</summary><span>${h(figure.context)}</span></details>`:''}</figcaption></figure>`}).join('')}</div>`:''}${binaries.length?`<p class="muted">기타 내부 바이너리 ${binaries.length}개</p>`:''}</details>`;}
async function loadAssetPreviews(){await Promise.all([...document.querySelectorAll<HTMLImageElement>("[data-asset-preview]")].map(async img=>{try{const blob=await apiBlob(`/assets/${img.dataset.assetPreview}/content`);const url=URL.createObjectURL(blob);assetObjectUrls.push(url);img.src=url;img.onload=()=>img.parentElement?.classList.add("loaded");}catch{img.alt="이미지 미리보기를 불러오지 못했습니다.";img.parentElement?.classList.add("failed");}}));}
async function showNotice(id:number){ selectedNotice=id; assetObjectUrls.forEach(URL.revokeObjectURL);assetObjectUrls=[]; const n=await api(`/notices/${id}`);const assets:Asset[]=n.assets||[];const attachments=assets.filter(a=>!documentInternalKinds.has(a.kind));const internal=assets.filter(a=>documentInternalKinds.has(a.kind)); const el=document.querySelector("#notice-detail")!; el.innerHTML=`<span class="eyebrow">${h(n.source)} · ${h(n.category)}</span><h2>${h(n.title)}</h2><div class="metadata"><span>게시 ${h(n.posted_at)}</span><span>추출 버전 ${h(n.extraction_version||'없음')}</span><span>임베딩 모델 ${h((n.embedding_models||[]).join(', ')||'없음')}</span><span>추출 신뢰도 ${n.extraction_confidence==null?'없음':Math.round(n.extraction_confidence*100)+'%'}</span><span>용량 ${formatBytes(n.storage_bytes)}</span><button id="open-original" class="text-link">원문</button></div><h3>저장된 본문</h3><div class="stored-body">${richText(n.body_content||n.content||'본문 없음')}</div><h3>첨부파일 ${attachments.length?attachments.length+'개':''}</h3>${attachments.length?attachments.map(attachmentMarkup).join(''):'<p class="muted">첨부 없음</p>'}${documentAnalysisMarkup(internal)}`; document.querySelector<HTMLButtonElement>("#open-original")!.onclick=()=>openExternal(n.url);document.querySelectorAll<HTMLButtonElement>("[data-external-url]").forEach(button=>button.onclick=()=>openExternal(button.dataset.externalUrl!));await loadAssetPreviews(); }
async function openExternal(url:string){try{await invoke("open_external_url",{url});}catch(error){toast(String(error),true)}}
async function accounts(){ const d=await api("/accounts"); document.querySelector("#view")!.innerHTML=`<article class="panel"><div class="list-head"><h3>가입 계정 ${d.items.length}개</h3><span class="muted">공식 포털 비밀번호는 저장하거나 변경하지 않습니다.</span></div><div class="account-grid">${d.items.map((a:Account)=>`<div class="account"><div><strong>${h(a.username)}</strong><span>${h(a.email||'이메일 없음')}</span></div><div><span>${h(a.student_id||'포털 미연결')}</span><span>${h(a.major||'학과 없음')} ${a.year?`${a.year}학년`:''}</span></div><button data-edit="${a.id}" class="ghost">수정</button><button data-delete="${a.id}" class="danger">삭제</button></div>`).join('')}</div></article>`; const map=new Map<number,Account>(d.items.map((a:Account)=>[a.id,a])); document.querySelectorAll<HTMLButtonElement>("[data-edit]").forEach(b=>b.onclick=()=>editAccount(map.get(Number(b.dataset.edit))!)); document.querySelectorAll<HTMLButtonElement>("[data-delete]").forEach(b=>b.onclick=async()=>{const id=Number(b.dataset.delete);if(!confirm("KNU 서비스 계정을 삭제할까요? 공주대 공식 포털 계정은 삭제되지 않습니다."))return;const linked=confirm("연결된 학적·시간표·LMS 데이터도 함께 삭제할까요?\n취소를 누르면 서비스 계정만 삭제합니다.");await api(`/accounts/${id}?delete_linked_data=${linked}`,{method:"DELETE"});toast("계정을 삭제했습니다.");accounts();}); }
function editAccount(a:Account){ const dialog=document.createElement("dialog"); dialog.innerHTML=`<form method="dialog" class="form"><h3>계정 수정</h3>${[["username","사용자명",a.username],["email","이메일",a.email],["student_id","학번",a.student_id],["name","이름",a.name],["major","학과",a.major],["year","학년",a.year]].map(([id,l,v])=>`<label>${l}<input id="e-${id}" value="${h(v)}"/></label>`).join('')}<div class="actions"><button value="cancel" class="ghost">취소</button><button id="edit-save" value="default">저장</button></div></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector<HTMLButtonElement>("#edit-save")!.onclick=async e=>{e.preventDefault();const val=(id:string)=>(dialog.querySelector(`#e-${id}`) as HTMLInputElement).value||null;await api(`/accounts/${a.id}`,{method:"PUT",body:JSON.stringify({username:val("username"),email:val("email"),student_id:val("student_id"),name:val("name"),major:val("major"),year:val("year")?Number(val("year")):null})});dialog.close();dialog.remove();toast("계정을 수정했습니다.");accounts();};dialog.onclose=()=>dialog.remove(); }
async function logs(){ await refreshRuntime(); document.querySelector("#view")!.innerHTML=`<article class="panel"><div class="list-head"><h3>최근 로그</h3><button id="clear-logs" class="ghost">비우기</button></div><pre class="logs">${h(runtime.logs.join('\n')||'아직 로그가 없습니다.')}</pre></article>`; document.querySelector<HTMLButtonElement>("#clear-logs")!.onclick=async()=>{await invoke("clear_logs");logs();}; }

