  document.querySelector<HTMLButtonElement>("#run-now")!.onclick=async()=>{try{const value=request();if(!value.source_codes.length){toast("수집 소스를 하나 이상 선택하세요.",true);return;}await save(false);await api("/crawl/run",{method:"POST",body:JSON.stringify(value)});toast("공지 수집을 시작했습니다.");await collection('crawl');}catch(e){toast(String(e),true)}};
  const pauseButton=document.querySelector<HTMLButtonElement>("#pause-crawl");if(pauseButton)pauseButton.onclick=async()=>{try{await api(paused?"/crawl/resume":"/crawl/pause",{method:"POST"});toast(paused?"공지 수집을 재개합니다.":"현재 작업을 일시정지합니다.");await collection('crawl');}catch(e){toast(String(e),true)}};
  const stopButton=document.querySelector<HTMLButtonElement>("#stop-crawl");if(stopButton)stopButton.onclick=async()=>{try{await api("/crawl/stop",{method:"POST"});toast("진행 중인 작업을 취소하고 체크포인트를 보존합니다.");await collection('crawl');}catch(e){toast(String(e),true)}};
